 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The guide is the full-length line of color 2; the irregular non-background
    # object is moved against that guide, and a central 8 separator is drawn.
    guide = 2
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, guide)]
    if not pts:
        return [row[:] for row in grid]
    rows = [r for r in range(h) if all(grid[r][c] == guide for c in range(w))]
    cols = [c for c in range(w) if all(grid[r][c] == guide for r in range(h))]
    out = [[bg] * w for _ in range(h)]
    # Preserve the guide line.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == guide:
                out[r][c] = guide
    if rows:
        gr = rows[0]
        # Keep all cells' shape and slide it toward the horizontal guide until
        # its closest edge is immediately adjacent to it.
        dr = (gr - 1 - max(r for r, c in pts)) if gr > max(r for r, c in pts) else (gr + 1 - min(r for r, c in pts))
        for r, c in pts:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        line = h // 2 + 1
        if line < h:
            for c in range(w):
                if out[line][c] != guide:
                    out[line][c] = 8
    elif cols:
        gc = cols[0]
        dc = (gc - 1 - max(c for r, c in pts)) if gc > max(c for r, c in pts) else (gc + 1 - min(c for r, c in pts))
        for r, c in pts:
            nc = c + dc
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        line = w // 2 + 1
        if line < w:
            for r in range(h):
                if out[r][line] != guide:
                    out[r][line] = 8
    return out

if __name__ == '__main__':
